import { ref, computed, onMounted } from 'vue';
import { ElTable, ElTableColumn, ElButton } from 'element-plus';
import { useStore } from 'vuex'; // 导入 Vuex Store

export default {
  __name: 'OrdersPage',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const store = useStore(); // 获取 Vuex Store
    const orders = ref([]); // 存储订单数据

    // 获取用户订单数据
    const fetchOrders = async () => {
      try {
        const response = await store.dispatch('FetchOrders'); // 从Vuex或API获取用户订单数据
        orders.value = response; // 假设返回的数据是一个订单数组
      } catch (error) {
        console.error('获取订单失败:', error);
      }
    };

    // 查看订单详情
    const viewOrderDetails = orderId => {
      console.log(`查看订单详情: ${orderId}`);
      // 跳转到订单详情页面，实现相应的 navigatation 逻辑
    };

    // 取消订单
    const cancelOrder = async orderId => {
      try {
        await store.dispatch('CancelOrder', orderId); // 调用 Vuex action 来取消订单
        await fetchOrders(); // 取消成功后重新获取订单列表
      } catch (error) {
        console.error('取消订单失败:', error);
      }
    };
    onMounted(fetchOrders); // 组件加载时获取订单数据

    const __returned__ = {
      store,
      orders,
      fetchOrders,
      viewOrderDetails,
      cancelOrder,
      ref,
      computed,
      onMounted,
      get ElTable() {
        return ElTable;
      },
      get ElTableColumn() {
        return ElTableColumn;
      },
      get ElButton() {
        return ElButton;
      },
      get useStore() {
        return useStore;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
